#!/usr/bin/env node
import { program } from 'commander';
import createDb from './commands/create-db';
import deleteDb from './commands/delete-db';
import listDatabases from './commands/list-dbs';
import login from './commands/login';
import logout from './commands/logout';
import selectRegion from './commands/select-region';

export const CLI_VERSION = require('../package.json')?.version || 'unknown';
program.version(CLI_VERSION, '-v, -V, --version', 'output the version number');

program
  .command('*')
  .description('create new db: mkdb uber_for_handstuff')
  .action(async (...args) => {
    const userInput = args?.at(1)?.args?.join(' ');
    await createDb(userInput);
  });

program
  .command('list')
  .description('list your current databases')
  .action(() => {
    listDatabases();
  });

program
  .command('region')
  // .argument('<id>', 'database id to delete')
  .description('select default db region')
  .action(() => {
    selectRegion();
  });

program
  .command('delete')
  .argument('<id>', 'database id to delete')
  .description('delete a database')
  .action((id) => {
    deleteDb(id);
  });

program
  .command('login')
  .description('login to mkdb cli')
  .action(() => login());

program
  .command('logout')
  .description('logout of mkdb cli')
  .action(() => {
    logout();
  });

program.parse(process.argv);
